var e=JSON.parse(`[{"id":"disc.processo_legislativo.ricd_proposicoes.0001","disciplina":"processo_legislativo","subtopico":"processo_legislativo.regimentos.ricd_proposicoes","tipo":"questao","titulo":"Regime de urgência no Regimento Interno da Câmara","comando":"O regime de urgência é um dos instrumentos que mais alteram o ritmo da tramitação na Câmara dos Deputados. Considerando o Regimento Interno da Câmara dos Deputados (Resolução nº 17/1989), redija um texto dissertativo, em até 20 linhas, abordando os seguintes aspectos:\\n\\n1. o que a urgência dispensa e o que ela preserva na tramitação de uma proposição;\\n2. as hipóteses em que a urgência pode ser requerida e quem tem legitimidade para requerê-la;\\n3. a diferença entre a urgência ordinária e a chamada urgência urgentíssima, inclusive quanto ao quórum de aprovação do requerimento.","linhas":20,"pontos":15,"tempoMin":30,"estrutura":[{"parte":"Introdução","dica":"Diga em uma frase o que é a urgência (dispensa de exigências regimentais para apreciar logo a matéria) e anuncie os três aspectos."},{"parte":"Aspecto 1: o que dispensa e o que preserva","dica":"Dispensa interstícios, prazos e formalidades; preserva pareceres (ou parecer oral), quórum e publicação/distribuição dos avulsos."},{"parte":"Aspecto 2: hipóteses e legitimados","dica":"Quatro hipóteses do art. 153 e três legitimados do art. 154 (Mesa, 1/3 dos Deputados ou Líderes equivalentes, 2/3 da comissão de mérito)."},{"parte":"Aspecto 3: urgência x urgência urgentíssima","dica":"Art. 155: matéria de relevante e inadiável interesse nacional; requerimento da maioria absoluta ou de Líderes que a representem; aprovado pela maioria absoluta; entra de imediato na Ordem do Dia."},{"parte":"Conclusão","dica":"Feche: a urgência acelera sem suprimir o exame da matéria; a urgentíssima é a forma mais intensa, por isso exige maioria absoluta."}],"quesitos":[{"id":"q1","texto":"Explica que a urgência dispensa exigências, interstícios e formalidades regimentais para que a proposição seja apreciada logo (art. 152).","pontos":2.5},{"id":"q2","texto":"Indica o que a urgência não dispensa: publicação e distribuição dos avulsos (que podem ser em cópia), pareceres das comissões ou de relator designado (que podem ser orais) e quórum de deliberação (art. 152, § 1º).","pontos":2.5},{"id":"q3","texto":"Cita as hipóteses do art. 153: defesa da sociedade democrática e das liberdades fundamentais; providência para atender a calamidade pública; prorrogação de prazos legais ou lei para época certa e próxima; apreciação da matéria na mesma sessão.","pontos":3},{"id":"q4","texto":"Indica os legitimados do art. 154: dois terços da Mesa (matéria de sua competência), um terço dos Deputados ou Líderes que representem esse número, dois terços dos membros da comissão competente para o mérito.","pontos":3},{"id":"q5","texto":"Distingue a urgência urgentíssima (art. 155): matéria de relevante e inadiável interesse nacional, requerimento da maioria absoluta dos Deputados ou de Líderes que a representem, aprovação pela maioria absoluta, com inclusão imediata na Ordem do Dia mesmo que iniciada a sessão.","pontos":4}],"modelo":"A urgência é o regime de tramitação que dispensa exigências, interstícios e formalidades regimentais para que determinada proposição seja apreciada de pronto pela Câmara dos Deputados. Ela altera o ritmo do processo legislativo, mas não suprime o seu núcleo, como se vê em três pontos.\\n\\nQuanto ao alcance, o art. 152 do Regimento Interno dispensa prazos e interstícios, mas preserva a publicação e a distribuição dos avulsos, ainda que em cópia, os pareceres das comissões ou de relator designado, que podem ser proferidos oralmente, e o quórum para deliberação. Em outras palavras, abrevia-se o caminho, não o exame da matéria.\\n\\nQuanto ao cabimento, o art. 153 admite a urgência quando a matéria envolve a defesa da sociedade democrática e das liberdades fundamentais, quando se trata de providência para atender a calamidade pública, quando se visa à prorrogação de prazos legais a findar ou a lei aplicável a época certa e próxima, ou quando se pretende a apreciação na mesma sessão. Podem requerê-la, nos termos do art. 154, dois terços da Mesa, em matéria de sua competência, um terço dos Deputados ou Líderes que representem esse número, e dois terços dos membros da comissão competente para opinar sobre o mérito.\\n\\nA urgência urgentíssima do art. 155 é mais intensa: reservada a matéria de relevante e inadiável interesse nacional, depende de requerimento da maioria absoluta dos Deputados ou de Líderes que a representem e de aprovação pela maioria absoluta, e a proposição entra de imediato na Ordem do Dia, ainda que a sessão já tenha começado. Assim, a urgência acelera sem calar o debate, e a sua forma extrema exige o apoio da maioria da Casa.","memoria":["Urgência (art. 152): dispensa exigências, interstícios e formalidades; preserva avulsos, pareceres (podem ser orais) e quórum.","Hipóteses (art. 153): liberdades fundamentais, calamidade pública, prazos legais ou lei para época certa, apreciação na mesma sessão.","Legitimados (art. 154): 2/3 da Mesa; 1/3 dos Deputados ou Líderes equivalentes; 2/3 da comissão de mérito.","Urgentíssima (art. 155): relevante e inadiável interesse nacional; maioria absoluta requer e maioria absoluta aprova; entra na Ordem do Dia na hora."],"chaves":["interstícios","avulsos","parecer oral","quórum","maioria absoluta","Ordem do Dia"],"errosComuns":["Dizer que a urgência dispensa o parecer: ela dispensa o prazo, não o parecer, que pode ser oral.","Confundir o quórum do requerimento de urgência comum (maioria simples) com o da urgentíssima (maioria absoluta).","Atribuir a urgentíssima a um terço dos Deputados: é a maioria absoluta."],"fonte":"Regimento Interno da Câmara dos Deputados (Res. 17/1989), arts. 152 a 155","tags":["discursiva","ricd"],"exemplo":true},{"id":"disc.processo_legislativo.apreciacao_conclusiva.0001","disciplina":"processo_legislativo","subtopico":"processo_legislativo.procedimento_legislativo.comissoes_pareceres","tipo":"questao","titulo":"Apreciação conclusiva pelas comissões","comando":"Situação hipotética: O Projeto de Lei nº 3.105, de 2026 (número, nomes e conteúdo fictícios), do Deputado Álvaro Nunes, que obriga a presença de intérprete de Libras nas audiências públicas dos órgãos federais, foi distribuído à Comissão de Defesa dos Direitos das Pessoas com Deficiência, para o mérito, e à Comissão de Constituição e Justiça e de Cidadania (CCJC), para os fins do art. 54 do Regimento Interno, em regime de tramitação ordinária e sujeito à apreciação conclusiva. A primeira comissão aprovou o projeto, sem emendas, e a CCJC concluiu pela constitucionalidade e pela juridicidade. Publicado o anúncio do encerramento da apreciação, a Deputada Marta Lins apresentou, na quarta sessão do prazo, recurso para que o projeto fosse apreciado pelo Plenário, com 49 assinaturas. Um Líder sustentou, então, que o parecer da CCJC, por ser terminativo, já teria encerrado a tramitação na Câmara.\\n\\nConsiderando essa situação hipotética, a Constituição Federal e o Regimento Interno da Câmara dos Deputados (Resolução nº 17/1989), redija um texto dissertativo, em até 20 linhas, abordando os seguintes aspectos:\\n\\n1. o fundamento constitucional e o conceito de apreciação conclusiva;\\n2. os projetos excluídos da apreciação conclusiva pelo Regimento Interno e a razão de o PL nº 3.105/2026 não estar entre eles;\\n3. a validade do recurso apresentado (legitimidade, prazo e efeitos), o destino do projeto quando não há recurso válido e a resposta ao argumento do Líder, com a diferença entre parecer conclusivo e parecer terminativo.","linhas":20,"pontos":15,"tempoMin":30,"estrutura":[{"parte":"Introdução","dica":"Comissões decidem em lugar do Plenário; anuncie fundamento, exceções e recurso, aplicados ao PL nº 3.105/2026."},{"parte":"Aspecto 1: fundamento e conceito","dica":"CF, art. 58, § 2º, I; RICD, arts. 24, II, e 132, III: dispensada a competência do Plenário."},{"parte":"Aspecto 2: exceções (art. 24, II)","dica":"PLP, código, iniciativa popular, de Comissão, matéria indelegável (art. 68, § 1º), do Senado aprovado pelo Plenário de qualquer Casa, pareceres divergentes, urgência. O PL do caso é de lei ordinária, de Deputado, sem urgência e com pareceres convergentes."},{"parte":"Aspecto 3: recurso e destino","dica":"1/10 dos membros (52), 5 sessões da publicação, ao Presidente, indicando o que vai ao Plenário (arts. 58 e 132, § 2º): prazo cumprido, mas 49 assinaturas não bastam. Sem recurso válido: redação final; 72 horas ao Senado."},{"parte":"Conclusão: conclusivo x terminativo","dica":"Terminativo: CCJC (constitucionalidade, juridicidade) e CFT (adequação financeira) — art. 54; só encerra a tramitação quando contrário. A CCJC foi favorável: o Líder se engana."}],"quesitos":[{"id":"q1","texto":"Indica o fundamento constitucional (art. 58, § 2º, I) e define apreciação conclusiva como a deliberação da comissão sobre projeto de lei com dispensa da competência do Plenário (RICD, arts. 24, II, e 132, III).","pontos":3},{"id":"q2","texto":"Enumera as exceções do art. 24, II: projetos de lei complementar, de código, de iniciativa popular, de Comissão, sobre matéria indelegável (art. 68, § 1º, da CF), oriundos do Senado ou por ele emendados que tenham sido aprovados pelo Plenário de qualquer das Casas, com pareceres divergentes e em regime de urgência; e reconhece que o PL nº 3.105/2026, de lei ordinária, de Deputado, sem urgência e com pareceres convergentes, não se enquadra em nenhuma delas.","pontos":4},{"id":"q3","texto":"Descreve o recurso: assinado por um décimo dos membros da Casa, dirigido ao Presidente, no prazo de cinco sessões da publicação do anúncio, indicando o que será objeto de deliberação do Plenário, que decide se o provê (art. 58, §§ 1º a 3º, e art. 132, § 2º); no caso, o prazo foi cumprido, mas as 49 assinaturas não alcançam o décimo exigido (52 Deputados).","pontos":4},{"id":"q4","texto":"Indica o destino sem recurso ou com recurso improvido: redação final ou arquivamento; aprovada a redação final, envio ao Senado ou à sanção em setenta e duas horas (art. 58, §§ 4º e 5º); no caso, redação final e remessa ao Senado.","pontos":2},{"id":"q5","texto":"Distingue apreciação conclusiva de parecer terminativo: o da CCJC sobre constitucionalidade ou juridicidade e o da CFT sobre adequação financeira ou orçamentária (art. 54); responde ao Líder que o parecer terminativo só encerra a tramitação quando contrário, e a CCJC foi favorável.","pontos":2}],"modelo":"A apreciação conclusiva permite que as comissões decidam sobre projetos de lei sem o Plenário, e o caso do PL nº 3.105/2026 mostra seus limites.\\n\\nSeu fundamento é o art. 58, § 2º, I, da Constituição: as comissões podem discutir e votar projeto de lei que dispensar, na forma do regimento, a competência do Plenário, salvo recurso de um décimo dos membros da Casa (RICD, arts. 24, II, e 132, III).\\n\\nExcluem-se os projetos de lei complementar, de código, de iniciativa popular, de comissão, sobre matéria indelegável, oriundos do Senado ou por ele emendados que tenham sido aprovados pelo Plenário de qualquer das Casas, com pareceres divergentes ou em regime de urgência (art. 24, II). O PL do caso, de lei ordinária, de Deputado, em tramitação ordinária e com pareceres convergentes, sujeita-se ao regime.\\n\\nO recurso, dirigido ao Presidente em cinco sessões da publicação do anúncio, exige um décimo dos Deputados e deve indicar o que irá ao Plenário, que decide se o provê (arts. 58, §§ 1º a 3º, e 132, § 2º). A Deputada cumpriu o prazo, mas 49 assinaturas não atingem o mínimo de 52. Sem recurso válido, o projeto vai à redação final e, aprovada esta, ao Senado em setenta e duas horas (art. 58, §§ 4º e 5º).\\n\\nO Líder confunde os institutos: terminativo é o parecer da CCJC sobre constitucionalidade ou juridicidade e o da CFT sobre adequação financeira (art. 54), que só encerra a tramitação quando contrário. A CCJC foi favorável, e o que dispensa o Plenário é o caráter conclusivo da apreciação.","memoria":["CF, art. 58, § 2º, I: comissão vota projeto de lei dispensado o Plenário, salvo recurso de 1/10.","Exceções (art. 24, II): PLP, código, iniciativa popular, de Comissão, indelegável, Senado já aprovado em Plenário, pareceres divergentes, urgência.","Recurso: 1/10 dos membros, 5 sessões da publicação, ao Presidente, indicando o que vai ao Plenário.","Sem recurso: redação final ou arquivo; 72 horas ao Senado ou à sanção.","Terminativo (art. 54): CCJC (constitucionalidade, juridicidade) e CFT (adequação financeira).","No caso: prazo cumprido, mas 49 < 52 assinaturas; terminativo favorável não encerra nada."],"chaves":["apreciação conclusiva","dispensa do Plenário","recurso de um décimo","cinco sessões","pareceres divergentes","parecer terminativo"],"errosComuns":["Incluir projetos de lei complementar entre os sujeitos à apreciação conclusiva.","Atribuir o recurso a um terço ou à maioria absoluta: é um décimo dos membros da Casa.","Confundir parecer conclusivo (mérito, no lugar do Plenário) com terminativo (admissibilidade).","Aceitar o recurso por ter sido apresentado no prazo, sem conferir o número de assinaturas (um décimo de 513 = 52)."],"fonte":"Constituição Federal, art. 58, § 2º, I; Regimento Interno da Câmara dos Deputados (Res. 17/1989), arts. 24, II, 54, 58 e 132","tags":["discursiva","caso","ricd"]},{"id":"disc.processo_legislativo.veto.0001","disciplina":"processo_legislativo","subtopico":"processo_legislativo.procedimento_legislativo.sancao_veto","tipo":"questao","titulo":"Sanção, veto e apreciação do veto pelo Congresso","comando":"Situação hipotética: O Projeto de Lei nº 845, de 2026 (número e conteúdo fictícios), que cria o Cadastro Nacional de Cuidadores de Pessoas Idosas, foi aprovado pela Câmara dos Deputados e pelo Senado Federal e enviado à sanção. No 12º dia útil após o recebimento, o Presidente da República sancionou o projeto, mas vetou, por contrariedade ao interesse público, apenas a expressão \\"e de seus dependentes\\", contida no inciso II do art. 3º, e comunicou os motivos ao Presidente do Senado Federal no dia seguinte. Passados trinta dias do recebimento do veto, o Congresso Nacional ainda não o apreciou. Um Senador propõe que a votação seja secreta, para proteger os parlamentares de pressões, e um Deputado pergunta quem promulgará a parte vetada se o veto for rejeitado.\\n\\nConsiderando essa situação hipotética, a Constituição Federal e o Regimento Comum do Congresso Nacional, redija um texto dissertativo, em até 20 linhas, abordando os seguintes aspectos:\\n\\n1. a sanção expressa e a tácita e o prazo para a manifestação do Presidente da República, com a análise da tempestividade do veto;\\n2. os fundamentos do veto, sua extensão e a comunicação dos motivos, com a análise da regularidade do veto à expressão;\\n3. a apreciação do veto pelo Congresso Nacional (sessão, prazo, quórum, forma de votação e efeito do decurso do prazo) e a promulgação se o veto for rejeitado.","linhas":20,"pontos":15,"tempoMin":30,"estrutura":[{"parte":"Introdução","dica":"Sanção ou veto encerram a fase constitutiva; situe o PL nº 845/2026 e anuncie os três aspectos."},{"parte":"Aspecto 1: sanção","dica":"Casa que concluiu a votação envia ao Presidente; sanção expressa (a parte não vetada); silêncio em 15 dias úteis = sanção tácita (art. 66, § 3º); veto no 12º dia útil é tempestivo."},{"parte":"Aspecto 2: veto","dica":"Inconstitucionalidade (jurídico) ou interesse público (político, como no caso); total ou parcial; motivos ao Presidente do Senado em 48 horas (cumprido); só texto integral de artigo, parágrafo, inciso ou alínea: vetar a expressão é irregular."},{"parte":"Aspecto 3: apreciação e promulgação","dica":"Sessão conjunta, 30 dias, maioria absoluta de Deputados e de Senadores, votação aberta (EC 76/2013): nada de voto secreto; prazo vencido → sobrestamento; promulgação em 48 h pelo Presidente, depois Presidente e Vice do Senado."}],"quesitos":[{"id":"q1","texto":"Explica a sanção: a Casa que concluiu a votação envia o projeto ao Presidente da República, que pode sancioná-lo expressamente; o silêncio por quinze dias úteis importa sanção tácita (art. 66, caput e § 3º).","pontos":3},{"id":"q2","texto":"Indica os fundamentos do veto: inconstitucionalidade (veto jurídico) ou contrariedade ao interesse público (veto político), total ou parcial, no prazo de quinze dias úteis do recebimento, com comunicação dos motivos ao Presidente do Senado em quarenta e oito horas (art. 66, § 1º); no caso, o veto no 12º dia útil é tempestivo, e a comunicação no dia seguinte respeita as 48 horas.","pontos":3},{"id":"q3","texto":"Explica que o veto parcial só abrange texto integral de artigo, parágrafo, inciso ou alínea, o que impede vetar palavras ou expressões isoladas (art. 66, § 2º); por isso, o veto à expressão \\"e de seus dependentes\\" é irregular, pois deveria abranger todo o inciso II do art. 3º.","pontos":2},{"id":"q4","texto":"Descreve a apreciação: sessão conjunta, em trinta dias do recebimento, com rejeição apenas pela maioria absoluta dos Deputados e dos Senadores, em votação aberta (EC 76/2013), o que afasta a votação secreta proposta pelo Senador; esgotado o prazo, como no caso, o veto vai à ordem do dia da sessão imediata, sobrestadas as demais proposições (art. 66, §§ 4º e 6º; RCCN, art. 106).","pontos":4},{"id":"q5","texto":"Explica a promulgação após a rejeição do veto: pelo Presidente da República em quarenta e oito horas; na omissão, pelo Presidente do Senado e, depois, pelo Vice-Presidente do Senado (art. 66, §§ 5º e 7º).","pontos":3}],"modelo":"No caso do PL nº 845/2026, a sanção e o veto encerram a fase constitutiva, e o Congresso dará a última palavra sobre a parte vetada.\\n\\nPelo art. 66 da Constituição, o projeto aprovado vai ao Presidente da República, que pode sancioná-lo expressamente, como fez com a parte não vetada; o silêncio por quinze dias úteis importa sanção tácita (§ 3º). O veto deve ocorrer no mesmo prazo, contado do recebimento: o do caso, no 12º dia útil, é tempestivo.\\n\\nO veto funda-se na inconstitucionalidade (jurídico) ou na contrariedade ao interesse público (político), como aqui, e seus motivos vão ao Presidente do Senado em quarenta e oito horas, prazo respeitado (§ 1º). O veto parcial, porém, só abrange texto integral de artigo, parágrafo, inciso ou alínea (§ 2º), o que impede vetar palavras e inverter o sentido da norma. O veto à expressão \\"e de seus dependentes\\" é irregular: deveria alcançar todo o inciso II do art. 3º.\\n\\nO veto é apreciado em sessão conjunta, dentro de trinta dias do recebimento, e só é rejeitado pela maioria absoluta dos Deputados e dos Senadores, em votação aberta desde a EC nº 76/2013, o que afasta a proposta do Senador (§ 4º). Esgotado o prazo, como no caso, o veto vai à ordem do dia da sessão imediata, sobrestadas as demais proposições (§ 6º; RCCN, art. 106, § 3º).\\n\\nRejeitado o veto, o projeto vai à promulgação pelo Presidente da República em quarenta e oito horas; na omissão, promulga o Presidente do Senado e, depois, o Vice-Presidente (§§ 5º e 7º).","memoria":["Sanção expressa ou tácita (silêncio de 15 dias úteis).","Veto: 15 dias úteis do recebimento; jurídico (inconstitucional) ou político (interesse público); motivos ao Presidente do Senado em 48 h.","Veto parcial: texto integral de artigo, parágrafo, inciso ou alínea; nunca palavras.","Apreciação: sessão conjunta, 30 dias, maioria absoluta de Deputados e de Senadores, voto aberto (EC 76/2013).","Prazo esgotado: sobrestamento da pauta (CF, § 6º; RCCN, art. 106, § 3º).","Veto rejeitado: promulga o Presidente em 48 h; senão, Presidente do Senado; senão, Vice.","No caso: veto tempestivo (12º dia útil), mas irregular (expressão isolada); voto secreto não cabe."],"chaves":["sanção tácita","veto jurídico","veto político","veto parcial","sessão conjunta","maioria absoluta","sobrestamento","promulgação"],"errosComuns":["Contar o prazo do veto em dias corridos: são quinze dias úteis.","Afirmar que o veto ainda é apreciado por escrutínio secreto.","Dizer que o veto rejeitado volta ao Presidente para nova sanção: vai à promulgação.","Aceitar o veto de uma expressão isolada só porque foi feito no prazo e motivado."],"fonte":"Constituição Federal, art. 66 (redação da EC nº 76/2013 no § 4º); Regimento Comum do Congresso Nacional (Res. 1/1970-CN), art. 106","tags":["discursiva","caso","processo_legislativo"]},{"id":"disc.processo_legislativo.medida_provisoria.0001","disciplina":"processo_legislativo","subtopico":"processo_legislativo.materias_legislativas.medida_provisoria","tipo":"questao","titulo":"Tramitação e efeitos da rejeição da medida provisória","comando":"A medida provisória tem força de lei desde a edição, mas sua permanência no ordenamento depende do Congresso Nacional. Com base no art. 62 da Constituição Federal e na jurisprudência do Supremo Tribunal Federal, redija um texto dissertativo, em até 20 linhas, abordando os seguintes aspectos:\\n\\n1. os pressupostos e os principais limites materiais da medida provisória;\\n2. a tramitação no Congresso: comissão mista, Casa iniciadora, juízo prévio, prazos e regime de urgência com sobrestamento da pauta;\\n3. os efeitos da rejeição ou da perda de eficácia da medida provisória.","linhas":20,"pontos":15,"tempoMin":30,"estrutura":[{"parte":"Introdução","dica":"Ato com força de lei, mas provisório; anuncie pressupostos, tramitação e rejeição."},{"parte":"Aspecto 1: pressupostos e limites","dica":"Relevância e urgência; submissão imediata; vedações do § 1º (nacionalidade, direitos políticos, eleitoral, penal, processo, Judiciário e MP, orçamento salvo crédito extraordinário, lei complementar)."},{"parte":"Aspecto 2: tramitação","dica":"Comissão mista (§ 9º; ADI 4029); início na Câmara (§ 8º); juízo prévio (§ 5º); 60 + 60 dias, suspensos no recesso; 45 dias → urgência e sobrestamento (§ 6º; MS 27.931)."},{"parte":"Aspecto 3: rejeição ou caducidade","dica":"Perde eficácia desde a edição; decreto legislativo; sem ele em 60 dias, relações conservadas (§ 11); vedada reedição na mesma sessão legislativa (§ 10); PLV: MP vigora até sanção ou veto (§ 12)."}],"quesitos":[{"id":"q1","texto":"Indica os pressupostos de relevância e urgência, a força de lei e a submissão imediata ao Congresso, e cita limites materiais do § 1º (nacionalidade, cidadania, direitos políticos, partidos e direito eleitoral; direito penal e processual; organização do Judiciário e do Ministério Público; orçamento, salvo créditos extraordinários; matéria reservada a lei complementar).","pontos":3},{"id":"q2","texto":"Descreve a tramitação: parecer da comissão mista de Deputados e Senadores (§ 9º), obrigatório segundo o STF (ADI 4029), votação iniciada na Câmara (§ 8º) em sessões separadas e juízo prévio sobre os pressupostos antes do mérito (§ 5º).","pontos":4},{"id":"q3","texto":"Indica os prazos: sessenta dias prorrogáveis uma vez por igual período, suspensos no recesso; após quarenta e cinco dias, regime de urgência com sobrestamento das demais deliberações da Casa, limitado pelo STF (MS 27.931) às matérias que podem ser objeto de medida provisória.","pontos":4},{"id":"q4","texto":"Explica os efeitos da rejeição ou da perda de eficácia: perda desde a edição, decreto legislativo para disciplinar as relações jurídicas e, sem ele em sessenta dias, conservação das relações constituídas na vigência (§§ 3º e 11); vedação de reedição na mesma sessão legislativa (§ 10); e vigência integral da MP até a sanção ou o veto do projeto de lei de conversão (§ 12).","pontos":4}],"modelo":"A medida provisória é ato com força de lei editado pelo Presidente da República, mas provisório: sua sorte depende do Congresso Nacional.\\n\\nPelo art. 62 da Constituição, ela exige relevância e urgência e deve ser submetida de imediato ao Congresso. Não pode tratar de nacionalidade, cidadania, direitos políticos, partidos e direito eleitoral, de direito penal e processual, da organização do Judiciário e do Ministério Público, de orçamento, salvo créditos extraordinários, nem de matéria reservada a lei complementar, entre outros limites (§ 1º).\\n\\nA comissão mista de Deputados e Senadores emite parecer (§ 9º), etapa que o STF considerou obrigatória na ADI 4029. A votação começa na Câmara (§ 8º), em sessões separadas, e cada Casa faz juízo prévio sobre os pressupostos antes do mérito (§ 5º). A vigência é de sessenta dias, prorrogável uma vez por igual período, com suspensão no recesso (§§ 3º, 4º e 7º). Não apreciada em quarenta e cinco dias, a MP entra em regime de urgência e sobrestá as demais deliberações da Casa (§ 6º); no MS 27.931, o STF limitou o sobrestamento às matérias passíveis de medida provisória.\\n\\nRejeitada ou caduca, a MP perde eficácia desde a edição, e o Congresso deve disciplinar por decreto legislativo as relações dela decorrentes (§ 3º); sem decreto em sessenta dias, essas relações continuam regidas pela MP (§ 11). É vedada a reedição na mesma sessão legislativa (§ 10). Se aprovado projeto de lei de conversão que altere o texto, a MP vigora integralmente até a sanção ou o veto (§ 12).","memoria":["Relevância e urgência; força de lei; submissão imediata ao Congresso.","Vedações (§ 1º): direitos políticos e eleitoral, penal e processo, Judiciário e MP, orçamento (salvo crédito extraordinário), lei complementar.","Comissão mista obrigatória (ADI 4029); começa na Câmara; juízo prévio dos pressupostos.","60 + 60 dias, suspensos no recesso; 45 dias → urgência e sobrestamento (MS 27.931: só matérias passíveis de MP).","Rejeição: perde eficácia desde a edição; decreto legislativo em 60 dias, senão relações conservadas.","Sem reedição na mesma sessão legislativa; PLV: MP vigora até sanção ou veto."],"chaves":["relevância e urgência","comissão mista","juízo prévio","sobrestamento","decreto legislativo","projeto de lei de conversão","reedição"],"errosComuns":["Dizer que a votação da MP começa no Senado ou em sessão conjunta.","Afirmar que a rejeição produz efeitos só dali em diante: a perda de eficácia retroage à edição.","Ignorar que o sobrestamento, segundo o STF, não alcança matérias que não podem ser objeto de MP."],"fonte":"Constituição Federal, art. 62 (redação da EC nº 32/2001); STF, ADI 4029 (2012, parecer da comissão mista); STF, MS 27.931 (2017, alcance do sobrestamento da pauta)","tags":["discursiva","processo_legislativo"]},{"id":"disc.processo_legislativo.redacao_final.0001","disciplina":"processo_legislativo","subtopico":"processo_legislativo.regimentos.ricd_proposicoes","tipo":"peca","titulo":"Redação final de projeto de lei aprovado com emendas","comando":"O Plenário da Câmara dos Deputados concluiu a votação, em turno único, do projeto abaixo (número e texto fictícios), que seguiu à Comissão de Constituição e Justiça e de Cidadania para a redação final.\\n\\nTEXTO DO PROJETO:\\n\\"PROJETO DE LEI Nº 1.234, DE 2026\\nDispõe sobre legendas e transcrições nos vídeos institucionais.\\nO CONGRESSO NACIONAL decreta:\\nArt. 1º. Esta lei obriga os órgãos públicos a colocar legendas nos seus vídeos.\\nArt. 2º Os vídeos institucionais divulgados na internet pelos órgãos e entidades da administração pública federal direta e indireta deverão conter legendas em língua portuguesa.\\nParágrafo único: Os vídeos com duração superior a 30 minutos serão acompanhados, também, de transcrição integral em formato de texto acessível.\\nArt. 3º O descumprimento do disposto no artigo anterior sujeitará o responsável às sanções previstas na legislação aplicável.\\nArt. 4º Esta lei entra em vigor na data de sua publicação.\\nArt. 5º Revogam-se as disposições em contrário.\\"\\n\\nEMENDAS DE PLENÁRIO:\\nEmenda nº 1 (aprovada): no parágrafo único do art. 2º, substitua-se \\"30 minutos\\" por \\"10 minutos\\".\\nEmenda nº 2 (aprovada): acrescente-se ao art. 2º parágrafo com o seguinte teor: \\"As transmissões ao vivo terão legendagem em tempo real, admitida a geração automática, e a versão gravada será disponibilizada com legenda revisada em até 5 dias úteis.\\"\\nEmenda nº 3 (rejeitada): estende as obrigações aos Estados, ao Distrito Federal e aos Municípios.\\nEmenda nº 4 (aprovada): dê-se ao art. 4º a seguinte redação: \\"Esta lei entra em vigor 180 dias após a sua publicação.\\"\\n\\nRedija, em até 50 linhas, a REDAÇÃO FINAL do projeto, na conformidade do vencido, sanando os vícios de linguagem e de técnica legislativa à luz da Lei Complementar nº 95/1998, sem alterar o mérito, com o fecho próprio do documento. Ao final, acrescente NOTA DO RELATOR, de até 15 linhas, que indique as correções de forma feitas e seus fundamentos.","linhas":50,"pontos":30,"tempoMin":60,"estrutura":[{"parte":"Cabeçalho","dica":"REDAÇÃO FINAL; PROJETO DE LEI Nº 1.234, DE 2026; ementa que explicite objeto e âmbito; O CONGRESSO NACIONAL decreta:"},{"parte":"Art. 1º: objeto e âmbito","dica":"Substitua o enunciado genérico por objeto e âmbito de aplicação (LC 95, art. 7º)."},{"parte":"Art. 2º e parágrafos","dica":"Caput mantido; parágrafo único vira § 1º com 'dez minutos' (Emenda 1); § 2º com a Emenda 2 ('cinco dias úteis'); Emenda 3 fica de fora."},{"parte":"Arts. 3º e 4º","dica":"Remissão expressa ao art. 2º; vigência com vacância na fórmula do art. 8º, § 2º; sem cláusula genérica de revogação."},{"parte":"Fecho","dica":"Sala da Comissão, em __ de ______ de 2026. Deputado ______, Relator."},{"parte":"Nota do Relator","dica":"Vencido (RICD, art. 195); LC 95: ementa (art. 5º), objeto (art. 7º), articulação (art. 10), números por extenso e remissão expressa (art. 11, II, f e g), vigência (art. 8º), revogação (art. 9º); mérito intacto."}],"quesitos":[{"id":"q1","texto":"Apresenta o cabeçalho e o fecho do documento: 'REDAÇÃO FINAL', identificação do projeto, ementa que explicita objeto e âmbito, fórmula 'O CONGRESSO NACIONAL decreta:' e 'Sala da Comissão', data e assinatura do Relator.","pontos":4},{"id":"q2","texto":"Incorpora o vencido: as Emendas nºs 1, 2 e 4, aprovadas, e exclui a Emenda nº 3, rejeitada, sem alterar o mérito (RICD, art. 195).","pontos":6},{"id":"q3","texto":"Reescreve o art. 1º para indicar o objeto da lei e seu âmbito de aplicação (LC 95, art. 7º), em lugar do enunciado genérico.","pontos":4},{"id":"q4","texto":"Corrige a articulação e a linguagem: parágrafo único convertido em §§ 1º e 2º com a nova emenda, números por extenso ('dez minutos', 'cinco dias úteis') e remissão expressa ao art. 2º em lugar de 'artigo anterior' (LC 95, arts. 10 e 11, II, f e g).","pontos":6},{"id":"q5","texto":"Redige a cláusula de vigência com vacância na fórmula 'entra em vigor após decorridos ... dias de sua publicação oficial' (art. 8º, § 2º) e suprime a cláusula genérica de revogação (art. 9º).","pontos":4},{"id":"q6","texto":"Na nota do relator, lista as correções de forma com seus fundamentos (RICD, art. 195; LC 95, arts. 5º, 7º, 8º, 9º, 10 e 11) e afirma que elas não alteram o mérito aprovado.","pontos":6}],"modelo":"REDAÇÃO FINAL\\nPROJETO DE LEI Nº 1.234, DE 2026\\n\\nDispõe sobre a disponibilização de legendas e de transcrições nos vídeos institucionais dos órgãos e das entidades da administração pública federal.\\n\\nO CONGRESSO NACIONAL decreta:\\n\\nArt. 1º Esta Lei dispõe sobre a disponibilização de legendas e de transcrições nos vídeos institucionais divulgados na internet pelos órgãos e pelas entidades da administração pública federal direta e indireta.\\n\\nArt. 2º Os vídeos institucionais divulgados na internet pelos órgãos e pelas entidades da administração pública federal direta e indireta deverão conter legendas em língua portuguesa.\\n§ 1º Os vídeos com duração superior a dez minutos serão acompanhados, também, de transcrição integral em formato de texto acessível.\\n§ 2º As transmissões ao vivo terão legendagem em tempo real, admitida a geração automática, e a versão gravada será disponibilizada com legenda revisada em até cinco dias úteis.\\n\\nArt. 3º O descumprimento do disposto no art. 2º desta Lei sujeitará o responsável às sanções previstas na legislação aplicável.\\n\\nArt. 4º Esta Lei entra em vigor após decorridos 180 (cento e oitenta) dias de sua publicação oficial.\\n\\nSala da Comissão, em __ de ______ de 2026.\\nDeputado ______________\\nRelator\\n\\nNOTA DO RELATOR\\n1. A redação incorpora as Emendas nºs 1, 2 e 4, aprovadas, e exclui a Emenda nº 3, rejeitada, na conformidade do vencido (RICD, art. 195).\\n2. A ementa passou a explicitar o objeto e o âmbito da lei (LC nº 95/1998, art. 5º), e o art. 1º passou a indicá-los, em lugar de enunciado genérico (art. 7º).\\n3. Com o acréscimo da Emenda nº 2, o parágrafo único converteu-se em §§ 1º e 2º (art. 10, III).\\n4. Os números foram grafados por extenso, e a expressão \\"artigo anterior\\" foi substituída pela remissão expressa ao art. 2º (art. 11, II, f e g).\\n5. A cláusula de vigência adotou a fórmula legal das leis com vacância (art. 8º, § 2º), e suprimiu-se a cláusula genérica de revogação, que deve enumerar as normas revogadas (art. 9º).\\n6. As alterações são de forma e não modificam o mérito aprovado.","memoria":["Redação final = texto do vencido: emendas aprovadas entram, rejeitadas ficam de fora (RICD, art. 195).","Cabeçalho: REDAÇÃO FINAL, projeto, ementa com objeto e âmbito, O CONGRESSO NACIONAL decreta:","Art. 1º indica objeto e âmbito (LC 95, art. 7º).","Parágrafo único + novo parágrafo = §§ 1º e 2º; números por extenso; remissão expressa, nunca 'artigo anterior'.","Vigência: 'após decorridos X dias de sua publicação oficial' (art. 8º, § 2º); sem 'revogam-se as disposições em contrário' (art. 9º).","Fecho: Sala da Comissão, data, Deputado, Relator; nota: correções de forma, mérito intacto."],"chaves":["redação final","vencido","emenda de redação","ementa","cláusula de vigência","vacância","cláusula de revogação","remissão expressa"],"errosComuns":["Incluir a emenda rejeitada ou deixar de incluir uma aprovada.","Manter 'Revogam-se as disposições em contrário'.","Alterar o mérito (prazos, destinatários) a pretexto de corrigir a redação.","Manter 'parágrafo único' ao lado de um novo parágrafo."],"fonte":"Regimento Interno da Câmara dos Deputados, arts. 32, IV, q, 118, § 8º, e 195 a 199; Lei Complementar nº 95/1998, arts. 5º, 7º, 8º, 9º, 10 e 11","tags":["discursiva","peca","ricd","tecnica_legislativa"]},{"id":"disc.processo_legislativo.medida_provisoria.0002","disciplina":"processo_legislativo","subtopico":"processo_legislativo.materias_legislativas.medida_provisoria","tipo":"peca","titulo":"Parecer técnico sobre admissibilidade e tramitação de medida provisória","comando":"Situação hipotética: Em 2 de setembro de 2026, foi publicada no Diário Oficial da União a Medida Provisória nº 1.347, de 2026 (número, nomes e conteúdo fictícios), que institui o Programa Emergencial de Recuperação de Estradas Vicinais (Pró-Vicinal) e autoriza a União a conceder subvenção a Municípios em estado de calamidade pública decorrente das chuvas. A exposição de motivos informa que 214 Municípios tiveram o escoamento da produção agrícola interrompido. Além das regras do programa (arts. 1º a 5º), a medida provisória, no art. 6º, tipifica como crime, com pena de reclusão de dois a seis anos, o desvio dos recursos do programa e, no art. 7º, altera a Lei Complementar nº 101/2000 (Lei de Responsabilidade Fiscal) para excluir as transferências do programa dos limites nela previstos. Na comissão mista, o Deputado Paulo Arantes apresentou a Emenda nº 15, que prorroga por dez anos os contratos de arrendamento de terminais portuários. A comissão mista foi instalada, mas não votou o parecer no prazo de 14 dias, e a medida provisória completou 45 dias de vigência sem deliberação. A Secretaria-Geral da Mesa da Câmara dos Deputados formulou, então, três consultas: (i) a matéria pode ser levada ao Plenário da Câmara com parecer proferido em Plenário pelo relator da comissão mista?; (ii) o Plenário pode votar, na próxima semana, a PEC nº 12/2026 e o PLP nº 40/2026, já pautados?; (iii) como devem ser tratados os arts. 6º e 7º e a Emenda nº 15?\\n\\nNa qualidade de Analista Legislativo, elabore, em até 50 linhas, PARECER TÉCNICO dirigido à Secretaria-Geral da Mesa sobre a admissibilidade e a tramitação da MP nº 1.347/2026, com relatório, análise e conclusão, abordando necessariamente:\\n\\n1. os pressupostos constitucionais e o juízo prévio de admissibilidade em cada Casa;\\n2. as vedações materiais aplicáveis aos arts. 6º e 7º e a forma de saneá-las;\\n3. a obrigatoriedade do parecer da comissão mista;\\n4. os prazos de vigência e o efeito do decurso de 45 dias sobre a pauta da Câmara;\\n5. a admissibilidade da Emenda nº 15.","linhas":50,"pontos":30,"tempoMin":60,"estrutura":[{"parte":"Cabeçalho","dica":"PARECER TÉCNICO, interessado (Secretaria-Geral da Mesa) e assunto (admissibilidade e tramitação da MP nº 1.347/2026)."},{"parte":"I – Relatório","dica":"Resuma sem opinar: objeto da MP, arts. 6º e 7º, Emenda nº 15, comissão mista sem parecer em 14 dias, 45 dias vencidos, as três consultas."},{"parte":"II – Análise: pressupostos e vedações","dica":"Relevância e urgência; juízo prévio em cada Casa (CF, art. 62, § 5º; Res. 1/2002-CN, art. 8º); art. 6º = direito penal, art. 7º = lei complementar (§ 1º, I, b, e III); conversão não convalida; PLV supressivo + PDL (Res. 1/2002, art. 5º, §§ 3º e 4º)."},{"parte":"II – Análise: comissão mista, prazos e pauta","dica":"Parecer da comissão obrigatório (§ 9º; ADI 4029 afastou o parecer em Plenário); 60 + 60 dias, suspensos no recesso; 45 dias → urgência e sobrestamento (§ 6º); MS 27.931: só PL ordinária sobre matéria passível de MP, então PEC e PLP podem ser votados."},{"parte":"II – Análise: Emenda nº 15","dica":"Matéria estranha: indeferimento liminar pelo Presidente da comissão, recurso com apoio de 3 membros (Res. 1/2002, art. 4º, §§ 4º e 5º); ADI 5127 (jabutis); LC 95, art. 7º, II."},{"parte":"III – Conclusão e fecho","dica":"Responda às três consultas em alíneas; lembre os efeitos de rejeição ou caducidade; local, data e assinatura do Analista Legislativo."}],"quesitos":[{"id":"q1","texto":"Organiza a peça como parecer técnico: identificação (interessado e assunto), relatório objetivo do caso e das consultas, análise fundamentada, conclusão que responde a cada consulta e fecho com local, data e assinatura.","pontos":3},{"id":"q2","texto":"Expõe os pressupostos de relevância e urgência (art. 62, caput), relacionando-os aos fatos, e o juízo prévio de cada Casa sobre os pressupostos e a adequação financeira e orçamentária antes do mérito, com arquivamento se negados (art. 62, § 5º; Res. nº 1/2002-CN, art. 8º); menciona que o controle judicial desses pressupostos é excepcional.","pontos":5},{"id":"q3","texto":"Identifica que o art. 6º trata de direito penal e o art. 7º de matéria reservada a lei complementar, vedados à MP (art. 62, § 1º, I, b, e III); afirma que a conversão em lei não convalida o vício e propõe projeto de lei de conversão que suprima os dispositivos, com projeto de decreto legislativo para as relações jurídicas deles decorrentes (Res. nº 1/2002-CN, art. 5º, §§ 3º e 4º).","pontos":6},{"id":"q4","texto":"Responde que a MP não pode ir ao Plenário sem o parecer da comissão mista, etapa obrigatória (art. 62, § 9º), pois o STF, na ADI 4029, afastou o parecer proferido em Plenário por relator previsto no art. 6º, §§ 1º e 2º, da Res. nº 1/2002-CN; lembra que a votação começa na Câmara (§ 8º).","pontos":4},{"id":"q5","texto":"Indica a vigência de sessenta dias, prorrogável uma vez por igual período, contada da publicação e suspensa no recesso (§§ 3º, 4º e 7º), e o regime de urgência com sobrestamento das demais deliberações após 45 dias (§ 6º); conclui, com base no MS 27.931, que o sobrestamento só alcança projetos de lei ordinária sobre matéria passível de MP, de modo que a PEC e o PLP podem ser votados.","pontos":6},{"id":"q6","texto":"Conclui que a Emenda nº 15 é matéria estranha e deve ser indeferida liminarmente pelo Presidente da comissão mista, com recurso ao colegiado apoiado por três membros (Res. nº 1/2002-CN, art. 4º, §§ 4º e 5º), e fundamenta com a ADI 5127 (emendas sem pertinência temática em lei de conversão violam o princípio democrático e o devido processo legislativo) e com a LC nº 95/1998, art. 7º, II.","pontos":6}],"modelo":"PARECER TÉCNICO Nº __/2026\\nInteressado: Secretaria-Geral da Mesa\\nAssunto: admissibilidade e tramitação da Medida Provisória nº 1.347, de 2026 (Pró-Vicinal).\\n\\nI – RELATÓRIO\\nA MP nº 1.347/2026, publicada em 2 de setembro, institui o Pró-Vicinal e autoriza subvenção a Municípios em calamidade; o art. 6º tipifica crime, e o art. 7º altera a LC nº 101/2000. Na comissão mista, foi apresentada a Emenda nº 15, sobre arrendamentos portuários. A comissão não votou o parecer em 14 dias, e a MP superou 45 dias de vigência. Consulta-se sobre o envio ao Plenário, a pauta e o tratamento dos arts. 6º e 7º e da emenda.\\n\\nII – ANÁLISE\\n1. Pressupostos. A MP exige relevância e urgência (CF, art. 62, caput), aqui demonstradas pela interrupção do escoamento em 214 Municípios. Cada Casa, antes do mérito, decide em apreciação preliminar sobre os pressupostos e a adequação financeira e orçamentária; negados, a MP é arquivada (art. 62, § 5º; Res. nº 1/2002-CN, art. 8º). O controle judicial desse juízo é excepcional (STF, ADI 2213 MC).\\n2. Vedações. O art. 6º trata de direito penal, e o art. 7º, de matéria reservada a lei complementar, temas vedados à MP (art. 62, § 1º, I, b, e III). A conversão em lei não convalida o vício (STF, ADI 4048 MC). A comissão deve propor projeto de lei de conversão que suprima os dois artigos, votada primeiro a emenda saneadora, e projeto de decreto legislativo sobre as relações decorrentes dos textos suprimidos (Res. nº 1/2002-CN, art. 5º, §§ 3º e 4º).\\n3. Comissão mista. O parecer do colegiado é obrigatório (art. 62, § 9º). Na ADI 4029, o STF afastou o parecer proferido em Plenário por relator (Res. nº 1/2002-CN, art. 6º, §§ 1º e 2º). Sem ele, a Câmara, onde a votação se inicia (§ 8º), não pode deliberar.\\n4. Prazos e pauta. A MP vigora por sessenta dias, prorrogáveis uma vez por igual período, contados da publicação e suspensos no recesso (§§ 3º, 4º e 7º). Após 45 dias, entra em regime de urgência e sobrestá as demais deliberações legislativas da Casa (§ 6º; Res. nº 1/2002-CN, art. 9º). Segundo o STF (MS 27.931), o sobrestamento alcança só os projetos de lei ordinária sobre matéria passível de MP; a PEC nº 12/2026 e o PLP nº 40/2026 podem ser votados.\\n5. Emenda nº 15. A prorrogação de arrendamentos portuários não tem pertinência com a MP. A emenda estranha deve ser indeferida liminarmente pelo Presidente da comissão mista, com recurso ao colegiado apoiado por três membros (Res. nº 1/2002-CN, art. 4º, §§ 4º e 5º). Na ADI 5127, o STF julgou que esses \\"jabutis\\" violam o princípio democrático e o devido processo legislativo, com efeitos a partir de 2015. A LC nº 95/1998 também veda matéria estranha ao objeto da lei (art. 7º, II).\\n\\nIII – CONCLUSÃO\\nOpina-se: (a) pela impossibilidade de levar a MP ao Plenário sem parecer da comissão mista; (b) pela possibilidade de votar a PEC e o PLP; (c) pela supressão dos arts. 6º e 7º no projeto de lei de conversão, com decreto legislativo; (d) pelo indeferimento da Emenda nº 15. Rejeitada ou caduca, a MP perde eficácia desde a edição e não pode ser reeditada na mesma sessão legislativa (§§ 3º e 10).\\n\\nBrasília, __ de outubro de 2026.\\nAnalista Legislativo","memoria":["Parecer: identificação, relatório, análise por consulta, conclusão em alíneas, local, data e assinatura.","Relevância e urgência; juízo prévio em cada Casa, com adequação financeira (art. 62, § 5º; Res. 1/2002, art. 8º).","Penal e lei complementar não cabem em MP (§ 1º, I, b, e III); conversão não convalida (ADI 4048 MC).","Saneamento: PLV que suprime + PDL para as relações dos textos suprimidos (Res. 1/2002, art. 5º, § 4º).","Comissão mista obrigatória; nada de parecer em Plenário (ADI 4029).","60 + 60 dias, suspensos no recesso; 45 dias → urgência e sobrestamento (§ 6º).","MS 27.931: só trava PL ordinária sobre matéria passível de MP; PEC, PLP, PDL e PR seguem.","Emenda estranha: indeferimento liminar (Res. 1/2002, art. 4º, § 4º); ADI 5127 (jabutis); LC 95, art. 7º, II."],"chaves":["relevância e urgência","juízo prévio","vedações materiais","projeto de lei de conversão","comissão mista","sobrestamento","matéria estranha","pertinência temática","decreto legislativo"],"errosComuns":["Admitir que o relator da comissão mista dê parecer em Plenário: o STF exigiu o parecer do colegiado (ADI 4029).","Dizer que o trancamento impede votar PEC ou PLP: ele só alcança projetos de lei ordinária sobre matéria passível de MP (MS 27.931).","Afirmar que a aprovação do projeto de conversão sana o crime criado por MP.","Tratar a emenda estranha como questão de mérito, sem invocar o indeferimento liminar e a ADI 5127.","Transformar o parecer em dissertação, sem relatório nem conclusão que responda às consultas."],"fonte":"Constituição Federal, art. 62 (EC nº 32/2001); Resolução nº 1/2002-CN, arts. 4º a 9º; LC nº 95/1998, art. 7º, II; STF: ADI 2213 MC (controle dos pressupostos), ADI 4048 MC (conversão não convalida vício), ADI 4029 (2012, parecer da comissão mista), ADI 5127 (2015, emendas sem pertinência temática), MS 27.931 (2017, alcance do sobrestamento); prova discursiva Câmara 2026 (Cebraspe), peça de parecer técnico sobre medida provisória","tags":["discursiva","peca","parecer","caso","processo_legislativo"]},{"id":"disc.processo_legislativo.pec.0001","disciplina":"processo_legislativo","subtopico":"processo_legislativo.materias_legislativas.pec","tipo":"peca","titulo":"Parecer técnico sobre admissibilidade e tramitação de PEC","comando":"Situação hipotética: Em 3 de março de 2026, foi apresentada à Mesa da Câmara dos Deputados a Proposta de Emenda à Constituição nº 21, de 2026 (número, nomes e conteúdo fictícios), encabeçada pela Deputada Lúcia Mendonça, com 175 assinaturas válidas. A proposta, no art. 1º, autoriza a União a instituir, até 31 de dezembro de 2028, imposto provisório sobre movimentação financeira, com receita vinculada à reconstrução de áreas atingidas por desastres naturais, e, no art. 2º, determina que ao novo imposto não se apliquem o art. 150, III, b (anterioridade de exercício), e o art. 150, VI, a (imunidade recíproca), da Constituição Federal. Depois da apresentação, oito signatários pediram a retirada de suas assinaturas. Sabe-se, ainda, que, em novembro de 2025, o Plenário rejeitou proposta de emenda à Constituição de conteúdo idêntico ao do art. 1º e que não há em vigor intervenção federal, estado de defesa ou estado de sítio. O Presidente da Comissão de Constituição e Justiça e de Cidadania (CCJC) pediu parecer técnico sobre a admissibilidade e a tramitação da proposta.\\n\\nNa qualidade de Analista Legislativo, elabore, em até 50 linhas, PARECER TÉCNICO dirigido à Presidência da CCJC, com relatório, análise e conclusão, abordando necessariamente:\\n\\n1. a regularidade da iniciativa, considerada a retirada das assinaturas;\\n2. os limites circunstanciais e a vedação de nova proposta sobre matéria rejeitada;\\n3. os limites materiais aplicáveis ao art. 2º, a forma de a CCJC tratar o vício e o controle judicial preventivo;\\n4. a tramitação na Câmara depois do juízo de admissibilidade (comissão, prazos, emendas, turnos, interstícios e quórum) e a promulgação.","linhas":50,"pontos":30,"tempoMin":60,"estrutura":[{"parte":"Cabeçalho","dica":"PARECER TÉCNICO, interessado (Presidência da CCJC) e assunto (admissibilidade e tramitação da PEC nº 21/2026)."},{"parte":"I – Relatório","dica":"Autoria, 175 assinaturas, conteúdo dos arts. 1º e 2º, pedido de retirada de oito assinaturas, rejeição de proposta idêntica em 2025."},{"parte":"II – Análise: iniciativa e limites formais","dica":"1/3 = 171 Deputados (CF, art. 60, I; RICD, art. 201, I); assinaturas não se retiram depois da apresentação (RICD, art. 102, § 4º); sem intervenção, estado de defesa ou de sítio (art. 60, § 1º); irrepetibilidade só na mesma sessão legislativa (§ 5º)."},{"parte":"II – Análise: cláusulas pétreas","dica":"'Tendente a abolir' protege o núcleo essencial (ADI 2024); anterioridade = garantia individual e imunidade recíproca = forma federativa (ADI 939); art. 1º admissível; admissibilidade com emenda supressiva ou inadmissibilidade; MS preventivo de parlamentar (MS 20.257; MS 32.033)."},{"parte":"II – Análise: tramitação e promulgação","dica":"CCJC em 5 sessões; inadmitida, recurso do Autor com Líderes de 1/3; Comissão Especial, 40 sessões, emendas nas 10 primeiras com 171 assinaturas; interstício de 2 sessões; dois turnos, 5 sessões entre eles, 3/5 = 308 votos nominais; Senado; Mesas promulgam, sem sanção (art. 60, § 3º)."},{"parte":"III – Conclusão e fecho","dica":"Iniciativa regular, sem limite circunstancial ou temporal, admissível com a supressão do art. 2º; local, data e assinatura."}],"quesitos":[{"id":"q1","texto":"Organiza a peça como parecer técnico: identificação (interessado e assunto), relatório objetivo, análise fundamentada em tópicos, conclusão clara e fecho com local, data e assinatura.","pontos":3},{"id":"q2","texto":"Afirma que a iniciativa parlamentar exige um terço dos Deputados, 171 (CF, art. 60, I; RICD, art. 201, I), e que as assinaturas necessárias ao trâmite não podem ser retiradas depois da apresentação à Mesa (RICD, art. 102, § 4º), de modo que a iniciativa, com 175 subscritores, é regular.","pontos":5},{"id":"q3","texto":"Verifica a ausência de limites circunstanciais (intervenção federal, estado de defesa ou de sítio: CF, art. 60, § 1º; RICD, art. 201, II) e explica que a vedação de nova proposta sobre matéria rejeitada só vale na mesma sessão legislativa (art. 60, § 5º), por isso a rejeição de 2025 não impede a PEC de 2026.","pontos":4},{"id":"q4","texto":"Analisa o art. 60, § 4º: a proposta 'tendente a abolir' cláusula pétrea não pode ser deliberada (proteção do núcleo essencial, ADI 2024); o art. 2º afronta a anterioridade, garantia individual do contribuinte (inciso IV), e a imunidade recíproca, expressão da forma federativa (inciso I), como decidido na ADI 939; o art. 1º é admissível; a CCJC deve concluir pela admissibilidade com emenda supressiva do art. 2º ou pela inadmissibilidade; e qualquer Deputado pode impetrar mandado de segurança preventivo contra a deliberação (MS 20.257; MS 32.033).","pontos":8},{"id":"q5","texto":"Descreve a tramitação regimental: CCJC com cinco sessões para a admissibilidade; se inadmitida, apreciação preliminar em Plenário a requerimento do Autor com apoio de Líderes que representem um terço; se admitida, Comissão Especial com quarenta sessões para o mérito e emendas só perante ela, nas dez primeiras sessões, com um terço das assinaturas (RICD, art. 202, §§ 1º a 4º).","pontos":6},{"id":"q6","texto":"Descreve a fase de Plenário e a final: interstício de duas sessões após o parecer, dois turnos com interstício de cinco sessões, aprovação por três quintos dos membros (308 votos) em votação nominal, deliberação idêntica no Senado e promulgação pelas Mesas da Câmara e do Senado, com número de ordem, sem sanção nem veto (CF, art. 60, §§ 2º e 3º; RICD, arts. 202, §§ 5º a 7º, e 203).","pontos":4}],"modelo":"PARECER TÉCNICO Nº __/2026\\nInteressado: Presidência da Comissão de Constituição e Justiça e de Cidadania\\nAssunto: admissibilidade e tramitação da PEC nº 21, de 2026.\\n\\nI – RELATÓRIO\\nA PEC nº 21/2026, da Deputada Lúcia Mendonça e outros, apresentada com 175 assinaturas, autoriza a União a instituir, até 2028, imposto provisório sobre movimentação financeira vinculado à reconstrução de áreas atingidas por desastres e, no art. 2º, afasta a anterioridade de exercício e a imunidade recíproca. Depois da apresentação, oito signatários pediram a retirada das assinaturas. Proposta de igual conteúdo foi rejeitada em novembro de 2025.\\n\\nII – ANÁLISE\\n1. Iniciativa. A PEC de Deputados exige um terço da Casa, 171 assinaturas (CF, art. 60, I; RICD, art. 201, I). As assinaturas necessárias ao trâmite não podem ser retiradas depois da apresentação à Mesa (RICD, art. 102, § 4º); a iniciativa, com 175 subscritores, é regular.\\n2. Limites circunstanciais e temporal. Não há intervenção federal, estado de defesa ou estado de sítio (CF, art. 60, § 1º; RICD, art. 201, II). A vedação de nova proposta sobre matéria rejeitada alcança só a mesma sessão legislativa (art. 60, § 5º); a rejeição de 2025 não impede a proposta de 2026.\\n3. Limites materiais. Não se delibera proposta tendente a abolir as cláusulas do art. 60, § 4º, que protegem o núcleo essencial dos princípios, não sua redação literal (STF, ADI 2024). O art. 1º é admissível. O art. 2º repete o vício reconhecido na ADI 939: a anterioridade é garantia individual do contribuinte (inciso IV), e a imunidade recíproca protege a forma federativa (inciso I). A CCJC deve concluir pela admissibilidade com emenda supressiva do art. 2º ou pela inadmissibilidade. Qualquer Deputado pode impetrar mandado de segurança preventivo contra a deliberação de PEC tendente a abolir cláusula pétrea (STF, MS 20.257 e MS 32.033).\\n4. Tramitação. A CCJC tem cinco sessões para opinar sobre a admissibilidade (RICD, art. 202). Inadmitida, o Autor pode requerer apreciação preliminar em Plenário, com apoio de Líderes que representem um terço da Casa (§ 1º). Admitida, o Presidente designa Comissão Especial, com quarenta sessões para o mérito; emendas só perante ela, nas dez primeiras sessões, com 171 assinaturas e sem ofensa ao art. 60, § 4º (§§ 2º a 4º). Publicado o parecer e após interstício de duas sessões, a PEC vai à Ordem do Dia e é votada em dois turnos, com interstício de cinco sessões, aprovada por três quintos dos membros, 308 votos, em votação nominal (§§ 5º a 7º). Segue ao Senado, que delibera do mesmo modo.\\n5. Promulgação. Aprovada nas duas Casas, a emenda é promulgada pelas Mesas da Câmara e do Senado, com número de ordem, sem sanção nem veto (CF, art. 60, § 3º; RICD, art. 203, parágrafo único).\\n\\nIII – CONCLUSÃO\\nOpina-se pela regularidade da iniciativa, pela ausência de limite circunstancial ou temporal e pela admissibilidade da PEC nº 21/2026, com emenda supressiva do art. 2º, que tende a abolir garantia individual e a forma federativa.\\n\\nBrasília, __ de ______ de 2026.\\nAnalista Legislativo","memoria":["Iniciativa: 1/3 = 171 Deputados; assinatura não sai nem entra depois da apresentação (RICD, art. 102, § 4º).","Limites circunstanciais: intervenção federal, estado de defesa, estado de sítio (art. 60, § 1º).","Matéria rejeitada: nova PEC só em outra sessão legislativa (art. 60, § 5º).","Cláusulas pétreas protegem o núcleo essencial (ADI 2024); anterioridade e imunidade recíproca são pétreas (ADI 939).","CCJC: admissibilidade em 5 sessões; inadmitida, recurso do Autor com Líderes de 1/3.","Comissão Especial: 40 sessões; emendas só nela, nas 10 primeiras, com 171 assinaturas.","Plenário: interstício de 2 sessões; dois turnos com 5 sessões entre eles; 3/5 = 308 votos nominais.","Promulgam as Mesas da Câmara e do Senado, com número de ordem; não há sanção nem veto.","MS preventivo: Deputado pode impetrar contra PEC tendente a abolir cláusula pétrea (MS 20.257)."],"chaves":["iniciativa","cláusula pétrea","tendente a abolir","limites circunstanciais","sessão legislativa","Comissão Especial","dois turnos","três quintos","promulgação pelas Mesas"],"errosComuns":["Considerar a iniciativa prejudicada pela retirada das assinaturas depois da apresentação.","Aplicar o art. 60, § 5º, a matéria rejeitada em sessão legislativa anterior.","Dizer que a CCJC examina o mérito da PEC: ela examina só a admissibilidade; o mérito é da Comissão Especial.","Exigir maioria absoluta ou dois terços: o quórum é de três quintos, em cada turno e em cada Casa.","Mandar a emenda constitucional à sanção do Presidente da República."],"fonte":"Constituição Federal, art. 60; Regimento Interno da Câmara dos Deputados, arts. 102, § 4º, 201 a 203; STF: ADI 939 (1993, anterioridade e imunidade recíproca como cláusulas pétreas), ADI 2024 (2007, núcleo essencial), MS 20.257 (1980) e MS 32.033 (2013, controle preventivo por parlamentar); prova discursiva Câmara 2026 (Cebraspe), modelo de peça em forma de parecer técnico","tags":["discursiva","peca","parecer","caso","processo_legislativo","ricd"]}]`);export{e as default};